// These modules intentionally expose small browser globals and must initialise in
// this order. Awaited imports preserve that contract in both source and bundled
// builds while the application is migrated away from the legacy script layout.
await import('./access-gate.js');

// In a browser these UMD files publish themselves. During bundling Rollup reads
// their CommonJS branch, so bridge each explicit import back to the same global.
const chordEngine=await import('./chord-engine.js');
window.ChordEngine ||= chordEngine.default || chordEngine;
const structureEngine=await import('./structure-engine.js');
window.StructureEngine ||= structureEngine.default || structureEngine;
const utilityEngine=await import('./utility-engine.js');
window.UtilityEngine ||= utilityEngine.default || utilityEngine;
const notebookEngine=await import('./notebook-engine.js');
window.NotebookEngine ||= notebookEngine.default || notebookEngine;
const mobileWriteEngine=await import('./mobile-write-engine.js');
window.MobileWriteEngine ||= mobileWriteEngine.default || mobileWriteEngine;
const audioTrimEngine=await import('./audio-trim-engine.js');
window.AudioTrimEngine ||= audioTrimEngine.default || audioTrimEngine;
const sandboxData=await import('./sandbox-data.js');
window.CoWriterSandboxData ||= sandboxData.default || sandboxData;
await import('./field-exchange.js');
await import('./review-capture.js');
await import('./morning-lines.js');
await import('./sync-adapter.js');
await import('./local-repository.js');
