(() => {
  'use strict';

  const CREATIVE_KEYS=['songs','ideas','projects','customTunings','unattachedTakes','deletedSongs','tombstones'];
  const DEVICE_SONG_KEYS=['lastView','viewMemory','shapeView'];

  const clone=value=>value==null?value:structuredClone(value);
  const stableJson=value=>JSON.stringify(value);

  class LocalRepository {
    constructor({dbName,version=4,stateStore='app',audioStore='audio',assetStore='assets',outboxStore='outbox',stateKey='state'}){
      this.dbName=dbName;this.version=version;this.stateStore=stateStore;this.audioStore=audioStore;this.assetStore=assetStore;this.outboxStore=outboxStore;this.stateKey=stateKey;this.db=null;this.lastCreativeJson='';this.clientId='';this.writeChain=Promise.resolve();
    }

    async open(){
      this.db=await new Promise((resolve,reject)=>{const request=indexedDB.open(this.dbName,this.version);request.onupgradeneeded=()=>{const database=request.result;if(!database.objectStoreNames.contains(this.stateStore))database.createObjectStore(this.stateStore);if(!database.objectStoreNames.contains(this.audioStore))database.createObjectStore(this.audioStore);if(!database.objectStoreNames.contains(this.assetStore))database.createObjectStore(this.assetStore);if(!database.objectStoreNames.contains(this.outboxStore))database.createObjectStore(this.outboxStore,{keyPath:'id'});};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});
      this.clientId=await this.getRecord('device-client-id');if(!this.clientId){this.clientId=`device_${crypto.randomUUID?.()||`${Date.now()}_${Math.random().toString(36).slice(2)}`}`;await this.setRecord('device-client-id',this.clientId);}return this;
    }

    request(store,mode,action){return new Promise((resolve,reject)=>{let result,value;const tx=this.db.transaction(store,mode);try{result=action(tx.objectStore(store));}catch(error){reject(error);return;}if(result&&'onsuccess' in result)result.onsuccess=()=>{value=result.result;};tx.oncomplete=()=>resolve(result&&'onsuccess' in result?value:result);tx.onerror=()=>reject(tx.error||new Error(`IndexedDB ${mode} failed`));tx.onabort=()=>reject(tx.error||new Error(`IndexedDB ${mode} was aborted`));});}
    getRecord(key){return this.request(this.stateStore,'readonly',store=>store.get(key));}
    setRecord(key,value){return this.request(this.stateStore,'readwrite',store=>store.put(value,key));}
    getAudio(key){return this.request(this.audioStore,'readonly',store=>store.get(key));}
    setAudio(key,value){return this.request(this.audioStore,'readwrite',store=>store.put(value,key));}
    deleteAudio(key){return this.request(this.audioStore,'readwrite',store=>store.delete(key));}
    getAsset(key){return this.request(this.assetStore,'readonly',store=>store.get(key));}
    setAsset(key,value){return this.request(this.assetStore,'readwrite',store=>store.put(value,key));}
    deleteAsset(key){return this.request(this.assetStore,'readwrite',store=>store.delete(key));}
    listOutbox(){return this.request(this.outboxStore,'readonly',store=>store.getAll());}
    acknowledgeOperations(ids){if(!ids?.length)return Promise.resolve();return this.request(this.outboxStore,'readwrite',store=>ids.forEach(id=>store.delete(id)));}

    split(runtime){
      const creative={};CREATIVE_KEYS.forEach(key=>creative[key]=clone(runtime[key]));
      const device={};Object.keys(runtime).filter(key=>!CREATIVE_KEYS.includes(key)&&key!=='schemaVersion'&&key!=='syncMeta').forEach(key=>device[key]=clone(runtime[key]));
      device.songStates={};creative.songs=(creative.songs||[]).map(song=>{const copy=clone(song);device.songStates[copy.id]={};DEVICE_SONG_KEYS.forEach(key=>{device.songStates[copy.id][key]=clone(copy[key]);delete copy[key];});return copy;});
      return{creative,device};
    }

    join(envelope){
      if(!envelope||!envelope.creative||!envelope.device)return clone(envelope);
      const runtime={schemaVersion:envelope.schemaVersion,...clone(envelope.creative),...clone(envelope.device),syncMeta:clone(envelope.sync||{})};const songStates=runtime.songStates||{};delete runtime.songStates;
      runtime.songs=(runtime.songs||[]).map(song=>({...song,...clone(songStates[song.id]||{})}));return runtime;
    }

    async readState(){const stored=await this.getRecord(this.stateKey);if(stored?.creative&&stored?.device)this.lastCreativeJson=stableJson(stored.creative);else if(stored){this.lastCreativeJson=stableJson(this.split(stored).creative);}return this.join(stored);}

    async persistState(runtime){
      const {creative,device}=this.split(runtime),creativeJson=stableJson(creative),previous=await this.getRecord(this.stateKey),previousSync=previous?.sync||runtime.syncMeta||{},changed=creativeJson!==this.lastCreativeJson,revision=Number(previousSync.revision||0)+(changed?1:0),sync={clientId:this.clientId,revision,lastSavedAt:new Date().toISOString()};const envelope={schemaVersion:16,creative,device,sync};
      await new Promise((resolve,reject)=>{const stores=changed?[this.stateStore,this.outboxStore]:[this.stateStore],tx=this.db.transaction(stores,'readwrite');tx.objectStore(this.stateStore).put(envelope,this.stateKey);if(changed){const id=`op_${this.clientId}_${String(revision).padStart(12,'0')}`;tx.objectStore(this.outboxStore).put({id,clientId:this.clientId,revision,kind:'creative-state',createdAt:sync.lastSavedAt,payload:creative});}tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error('Local save failed'));tx.onabort=()=>reject(tx.error||new Error('Local save was aborted'));});
      this.lastCreativeJson=creativeJson;return sync;
    }

    async writeState(runtime){
      const snapshot=clone(runtime),pending=this.writeChain.then(()=>this.persistState(snapshot));
      this.writeChain=pending.catch(()=>{});
      const sync=await pending;runtime.syncMeta=sync;return sync;
    }
  }

  window.CoWriterLocalRepository={LocalRepository,create:options=>new LocalRepository(options),creativeKeys:CREATIVE_KEYS,deviceSongKeys:DEVICE_SONG_KEYS};
})();
