(() => {
  'use strict';

  class SyncAdapter {
    async push(){throw new Error('SyncAdapter.push must be implemented');}
    async pull(){throw new Error('SyncAdapter.pull must be implemented');}
    status(){return{state:'saved-here'};}
  }

  class LocalOnlySyncAdapter extends SyncAdapter {
    async push(){return{acknowledged:[]};}
    async pull(){return{operations:[]};}
    status(){return{state:'saved-here'};}
  }

  window.CoWriterSync={SyncAdapter,LocalOnlySyncAdapter};
})();
